input.command:
cd <out>/h15-everwrite-1
cat > scripts/lint-prose.js <<'EOF'
// Runs scripts/tells.py over README.md and every Markdown file under docs/.
// The checker's rules are English. Folders named after another language
// (docs/de, docs/fr) are skipped because dashes and „…“ quotes are normal there.
const { spawnSync } = require("node:child_process");
const fs = require("node:fs");
const path = require("node:path");

const root = path.join(__dirname, "..");
const skip = new Set(["de", "fr"]);

function collect(dir, out) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (dir === path.join(root, "docs") && skip.has(entry.name)) continue;
      collect(full, out);
    } else if (entry.name.endsWith(".md")) {
      out.push(full);
    }
  }
  return out;
}

const files = [path.join(root, "README.md"), ...collect(path.join(root, "docs"), [])];
const script = path.join(__dirname, "tells.py");

for (const py of ["python3", "python"]) {
  const r = spawnSync(py, [script, ...files], { stdio: "inherit", cwd: root });
  if (r.error && r.error.code === "ENOENT") continue;
  process.exit(r.status ?? 2);
}
console.error("lint:prose needs Python 3.9 or later (python3 or python on PATH).");
process.exit(2);
EOF
python3 - <<'EOF'
import re
p='package.json'; s=open(p).read()
s=s.replace('''"test": "node -e \\"console.log('tests ok')\\""''','''"test": "node -e \\"console.log('tests ok')\\"",
    "lint:prose": "node scripts/lint-prose.js"''')
open(p,'w').write(s)
p='README.md'; s=open(p).read()
s=s.replace('> "Let me','<!-- tells: off -->\n> "Let me').replace('Delete it.\n','Delete it.\n<!-- tells: on -->\n')
open(p,'w').write(s)
EOF
cat >> .github/workflows/ci.yml <<'EOF'
  lint-prose:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - run: npm run lint:prose
EOF
cat package.json; npm run lint:prose; echo "exit $?"
# temporarily test a new bad file and a new good file
printf '# X\n\nThis is a testament to robust, seamless work — really.\n' > docs/tmp-bad.md; npm run lint:prose >/dev/null; echo "bad exit $?"; rm docs/tmp-bad.md
mv docs/guide.md /tmp/guide.bak; npm run lint:prose | tail -1; echo "without guide exit $?"; mv /tmp/guide.bak docs/guide.md

